style.css:
@-moz-document domain("youtube.com") {
body {
        background: linear-gradient(135deg, #ff7e5f, #feb47b);
        /* Add more styles here, like custom font colors or margins */
    }
    
    /* Customize the background of the YouTube video container */
    ytd-app {
        background-color: rgba(255, 255, 255, 0.8); /* Slight transparency */
    }

    /* Add custom styles for other elements like sidebar, header */
    ytd-masthead {
        background-color: rgba(0, 0, 255, 0.6); /* Darken header */
    }

    ytd-guide-renderer {
        background-color: #222222; /* Darken the sidebar */
    }

    /* Styling the links */
    a {
        color: #f1c40f;
        text-decoration: none;
    }
    
    a:hover {
        color: #e67e22;
    }
}
